import logging
_logger = logging.getLogger(__name__)

configs = model.search([('active', '=', True)])
_logger.info("Zalo Stock Notification Token Refresh Cron: Found %s active config(s)", len(configs))

for config in configs:
    try:
        if config._is_token_expired():
            _logger.info("Refreshing token for config: %s", config.name)
            config.refresh_zalo_access_token()
        else:
            _logger.debug("Token for config %s is still valid", config.name)
    except Exception as e:
        _logger.error("Failed to refresh token for config %s: %s", config.name, str(e), exc_info=True)
